window.AUTH=window.AUTH||{};window.AUTH["23-411"]={"d":"23-411","id":"2023/23-411","n":"Murthy v. Missouri","briefs":[{"k":"petitioner","label":"Brief of petitioners Vivek H. Murthy, et al.","date":"2023-12-19","url":"https://www.supremecourt.gov/DocketPDF/23/23-411/293780/20231219192259919_23-411ts%20Murthy.pdf","side":"pet","n":49},{"k":"united-states","label":"Brief amicus curiae of United States Senator Mark Warner","date":"2023-12-26","url":"https://www.supremecourt.gov/DocketPDF/23/23-411/294259/20231226144150391_2023.12.26%20FOR%20PRINTER%20Senator%20Warner%20Amicus%20Brief%20-%20Murthy%20v%20Missouri.pdf","side":"us","n":2},{"k":"respondent","label":"Brief of respondents Missouri, et al.","date":"2024-02-02","url":"https://www.supremecourt.gov/DocketPDF/23/23-411/299644/20240202144405984_2024-02-02%20-%20Murthy%20v.%20Missouri%20-%20Brief%20of%20Respondents%20-%20Final%20with%20Tables.pdf","side":"res","n":76},{"k":"reply","label":"Reply of petitioners Vivek H. Murthy, et al.","date":"2024-03-04","url":"https://www.supremecourt.gov/DocketPDF/23/23-411/302221/20240304163443397_23-411rb%20Murthy.pdf","side":"pet","n":33}],"opinion":"https://www.supremecourt.gov/opinions/23pdf/603us1r49_n6io.pdf","tr":true,"items":[{"t":"case","label":"Adickes v. S.H. Kress & Co.","cite":"398 U.S. 144","y":1970,"id":"1969/79","sc":1,"by":{"0":"36","2":"32, 34, 36","3":"14, 15, 21"},"q":[{"src":"brief","b":2,"text":"plainly provide[] the state action essential","cite":"398 U.S. 144, 151-52, 158"}]},{"t":"case","label":"Already, LLC v. Nike, Inc.","cite":"568 U.S. 85","y":2013,"id":"2012/11-982","sc":1,"by":{"0":"28"},"q":[{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"never accepted such a boundless theory of standing.","cite":"568 U. S. 85, 99"}]},{"t":"case","label":"American Manufacturers Mutual Insurance Co. v. Sullivan","cite":"526 U.S. 40","y":1999,"id":"1998/97-2000","sc":1,"by":{"0":"35, 45"},"q":[{"src":"brief","b":0,"text":"begins by identifying ‘the specific conduct of which the plaintiff complains.’","cite":"526 U.S. 40, 51"},{"src":"brief","b":0,"text":"[a]ction taken by private entities with the mere approval or acquiescence of the [government] is not state action.","cite":"526 U.S. at 52"}]},{"t":"case","label":"Ashcroft v. American Civil Liberties Union","cite":"535 U.S. 564","y":2002,"id":"2001/00-1293","sc":1,"by":{"0":"23"}},{"t":"case","label":"Bantam Books, Inc. v. Sullivan","cite":"372 U.S. 58","y":1963,"id":"1962/118","sc":1,"by":{"0":"26, 27","2":"25, 30, 36, 38, 39, 41","3":"7, 8"},"q":[{"src":"brief","b":2,"text":"not likely to sustain sufficient economic injury to induce [them] to seek judicial vindication of [their] rights.","cite":"372 U.S. 58, 64 n.6"},{"src":"brief","b":2,"text":"Nice business you’ve got there. Would be a shame if something happened to it.","cite":"372 U.S. at 67"},{"src":"argument","who":"Mr. Fletcher","text":"Like Bantam Books, this case should be about that fundamental distinction between persuasion and coercion. But, unlike Bantam and the case that you'll hear next, this is not a typical suit where a speaker challenges government actions affecting its own speech."},{"src":"argument","who":"Justice Thomas","text":"Mr. Fletcher, is the coercion/encouragement framework out of Brant -- of Bantam Book the only way to look at this case?"},{"src":"argument","who":"Mr. Fletcher","text":"I think one of them is the coercion inquiry, which we think comes from Bantam Books. You can think of that as an aspect of state action because, when private parties are compelled to act, as the Court said in Halleck, they become state actors."}]},{"t":"case","label":"Blum v. Yaretsky","cite":"457 U.S. 991","y":1982,"id":"1981/80-1952","sc":1,"by":{"0":"26, 27","2":"32, 36, 50","3":"8, 13, 19"},"q":[{"src":"brief","b":0,"text":"normally can be held responsible for a private decision only when it has exercised coercive power or has provided such significant encouragement, either overt or covert, that the choice must in law be deemed to be that of the [government].","cite":"457 U.S. 991, 1004"},{"src":"brief","b":0,"text":"Mere approval of or acquiescence in the initiatives of a private party is not sufficient.","cite":"457 U.S. at 1004"},{"src":"brief","b":3,"text":"to assure that constitutional standards are invoked only when it can be said that the [government] is responsible for the specific conduct of which the plaintiff complains.","cite":"457 U.S. at 1004"},{"src":"argument","who":"Mr. Fletcher","text":"But you also see suits against the government based on conduct by private parties. That was the case in Blum, and that's the theory that Respondents are pursuing here."},{"src":"argument","who":"Justice Jackson","text":"So I guess I didn't perceive there to be such a sharp distinction between Blum and Bantam Books. The government seems to be arguing here that Bantam Books is the way to go, that Blum is not the right test."},{"src":"argument","who":"Mr. Fletcher","text":"I think the reason why you may have sensed me today and us in our briefs resisting Blum is because the lower courts and my friends on the other side have really tried to turn that \"significant encouragement\" language into something quite different, into circumstances where the government encourages in some colloquial sense by urging or persuading or, you know, really strongly advocating something."}]},{"t":"case","label":"Board of Regents v. Southworth","cite":"529 U.S. 217","y":2000,"id":"1999/98-1189","sc":1,"by":{"0":"23, 38","3":"16"},"q":[{"src":"brief","b":0,"text":"the government can speak for itself.","cite":"529 U.S. 217, 229"},{"src":"brief","b":0,"text":"advocate and defend its own policies,","cite":"529 U.S. at 229"}]},{"t":"case","label":"Brentwood Academy v. Tennessee Secondary School Athletic Association","cite":"531 U.S. 288","y":2001,"id":"2000/99-901","sc":1,"by":{"0":"43","2":"43, 44","3":"18, 19"},"q":[{"src":"brief","b":3,"text":"on the ex parte application of one party to a private dispute.","cite":"531 U.S. 288"}]},{"t":"case","label":"Califano v. Yamasaki","cite":"442 U.S. 682","y":1979,"id":"1978/77-1511","sc":1,"by":{"0":"46","2":"51, 52"},"q":[{"src":"brief","b":0,"text":"be no more burdensome to the defendant than necessary to provide complete relief to the plaintiffs.","cite":"442 U.S. 682, 702"},{"src":"brief","b":2,"text":"[T]he scope of injunctive relief is dictated by the extent of the violation established,","cite":"442 U.S. 682, 702"},{"src":"brief","b":2,"text":"the extent of the violation established,","cite":"442 U.S. at 702"}]},{"t":"case","label":"Carney v. Adams","cite":"141 S. Ct. 493","y":2020,"id":"2020/19-309","sc":1,"by":{"0":"16"},"q":[{"src":"brief","b":0,"text":"The doctrine of standing implements this requirement by insisting that a litigant ‘prove that he has suffered a concrete and particularized injury that is fairly traceable to the challenged conduct, and is likely to be redressed by a favorable judicial decision.’","cite":"141 S. Ct. 493, 498"}]},{"t":"case","label":"Changizi v. HHS","cite":"82 F.4th 492","y":2023,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.4th/82/492/","by":{"0":"18","3":"3"},"q":[{"src":"brief","b":0,"text":"‘an injury that results from a third party’s voluntary and independent actions’ does not establish traceability.","cite":"82 F.4th 492, 497"},{"src":"brief","b":3,"text":"its ‘broad and legitimate discretion’ as an independent company,","cite":"82 F.4th 492, 497"}]},{"t":"case","label":"City of Los Angeles v. Lyons","cite":"461 U.S. 95","y":1983,"id":"1982/81-1064","sc":1,"by":{"0":"19"}},{"t":"case","label":"Clapper v. Amnesty International USA","cite":"568 U.S. 398","y":2013,"id":"2012/11-1025","sc":1,"by":{"0":"20","2":"27"},"q":[{"src":"brief","b":0,"text":"cannot manufacture standing merely by inflicting harm on themselves based on their fears of hypothetical future harm that is not certainly impending.","cite":"568 U.S. 398, 416"},{"src":"brief","b":2,"text":"hypothetical future harm that is not certainly impending.","cite":"568 U.S. 398, 416"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"been reluctant to endorse standing theories that require guesswork as to how independent decisionmakers will exercise their judgment.","cite":"568 U. S., at 413"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"substantially undermines [the plaintiffs'] standing theory.","cite":"568 U. S., at 411"},{"src":"argument","who":"Justice Sotomayor","text":"Counsel, you don't do a lot with Clapper, and it seems that Clapper really does change all of the cases in terms of requiring a heightened traceability standard, does it not?"},{"src":"argument","who":"Mr. Fletcher","text":"So I -- I think Clapper does -- is very instructive here. We do cite and rely on it. We think it's relevant to traceability. We think it's perhaps most relevant at the -- sort of the future injury question because I think -- I think we're right about traceability of all of the past moderation of their content that they talk about, but I think we're on even stronger ground in saying that the vast majority of the things they're talking about are about COVID-19 or unusual, idiosyncratic stories from the 2020 election, and their burden is to show that they face an imminent threat -- that's from Ly …"}]},{"t":"case","label":"Colorado v. Connelly","cite":"479 U.S. 157","y":1986,"id":"1986/85-660","sc":1,"by":{"0":"40, 41"}},{"t":"case","label":"Counterman v. Colorado","cite":"600 U.S. 66","y":2023,"id":"2022/22-138","sc":1,"by":{"0":"38","2":"38, 41"},"q":[{"src":"brief","b":2,"text":"[t]he existence of a threat depends not on ‘the mental state of the author,’ but on ‘what the statement conveys’ to the person on the other end.","cite":"600 U.S. 66, 74"}]},{"t":"case","label":"Elrod v. Burns","cite":"427 U.S. 347","y":1976,"id":"1975/74-1520","sc":1,"by":{"0":"46","2":"49"},"q":[{"src":"brief","b":2,"text":"[t]he loss of First Amendment freedoms, for even minimal periods of time, unquestionably constitutes irreparable injury,","cite":"427 U.S. 347, 373"}]},{"t":"case","label":"Gill v. Whitford","cite":"138 S. Ct. 1916","y":2018,"id":"2017/16-1161","sc":1,"by":{"0":"46"},"q":[{"src":"brief","b":0,"text":"[a] plaintiff ’s remedy must be tailored to redress the plaintiff ’s particular injury.","cite":"138 S. Ct. 1916, 1933-1934"}]},{"t":"case","label":"Haaland v. Brackeen","cite":"599 U.S. 255","y":2023,"id":"2022/21-376","sc":1,"by":{"0":"20, 22","3":"7"},"q":[{"src":"brief","b":0,"text":"a thinly veiled attempt to circumvent the limits on parens patriae standing.","cite":"599 U.S. at 295 n.11"},{"src":"brief","b":3,"text":"a thinly veiled attempt to circumvent the limits on parens patriae standing.","cite":"599 U.S. 255, 295 n.11"},{"src":"opinion","who":"Opinion of the Court (Justice Barrett)","text":"[t]his argument is a thinly veiled attempt to circumvent the limits on parens patriae standing.","cite":"599 U. S., at 295, n. 11"}]},{"t":"case","label":"Harlow v. Fitzgerald","cite":"457 U.S. 800","y":1982,"id":"1981/80-945","sc":1,"by":{"0":"50","2":"50"},"q":[{"src":"brief","b":0,"text":"‘dampen the ardor of all but the most resolute, or the most irresponsible public officials, in the unflinching discharge of their duties.’","cite":"457 U.S. 800, 814"}]},{"t":"case","label":"INS v. Legalization Assistance Project","cite":"510 U.S. 1301","y":1993,"url":"https://supreme.justia.com/cases/federal/us/510/1301/","sc":1,"by":{"0":"49"}},{"t":"case","label":"Kennedy v. Warren","cite":"66 F.4th 1199","y":2023,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.4th/66/1199/","by":{"0":"42, 43"},"q":[{"src":"brief","b":0,"text":"‘removed from the relevant levers of power.’","cite":"66 F.4th 1199, 1210"}]},{"t":"case","label":"Kleindienst v. Mandel","cite":"408 U.S. 753","y":1972,"id":"1971/71-16","sc":1,"by":{"0":"21","2":"23, 24, 25"},"q":[{"src":"brief","b":0,"text":"referred to a First Amendment right to ‘receive information and ideas.’","cite":"408 U.S. 753, 762"},{"src":"brief","b":2,"text":"First Amendment right to ‘receive information and ideas,’ … ‘necessarily protects the right to receive.’","cite":"408 U.S. 753, 762-63"}]},{"t":"case","label":"Lewis v. Casey","cite":"518 U.S. 343","y":1996,"id":"1995/94-1511","sc":1,"by":{"0":"19, 47"}},{"t":"case","label":"Lugar v. Edmondson Oil Co.","cite":"457 U.S. 922","y":1982,"id":"1981/80-1730","sc":1,"by":{"0":"25","3":"18"},"q":[{"src":"brief","b":0,"text":"can be violated only by conduct that may be fairly characterized as ‘state action.’","cite":"457 U.S. 922, 924"},{"src":"brief","b":3,"text":"integral and, indeed, indispensable part of the State’s plan to operate","cite":"457 U.S. 922"}]},{"t":"case","label":"Manhattan Community Access Corp. v. Halleck","cite":"139 S. Ct. 1921","y":2019,"id":"2018/17-1702","sc":1,"by":{"0":"2, 3, 14, 16, 22, 25, 26, 28, 36","2":"1","3":"1, 2, 8, 13, 17, 18"},"q":[{"src":"brief","b":0,"text":"constitutional boundary between the governmental and the private.","cite":"139 S. Ct. 1921, 1928"},{"src":"brief","b":0,"text":"compels the private entity to take a particular action.","cite":"139 S. Ct. 1921, 1928"},{"src":"brief","b":2,"text":"The Free Speech Clause of the First Amendment constrains governmental actors and protects private actors.","cite":"139 S. Ct. 1921, 1926"},{"src":"brief","b":3,"text":"constitutional boundary between the governmental and the private,","cite":"139 S. Ct. 1921, 1928"},{"src":"brief","b":3,"text":"eviscerate certain private entities’ rights to exercise editorial control over speech and speakers on their properties or platforms.","cite":"139 S. Ct. at 1932"}]},{"t":"case","label":"McConnell v. FEC","cite":"540 U.S. 93","y":2003,"id":"2003/02-1674","sc":1,"by":{"0":"22"}},{"t":"case","label":"National Endowment for the Arts v. Finley","cite":"524 U.S. 569","y":1998,"id":"1997/97-371","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"the very business of government to favor and disfavor points of view.","cite":"524 U.S. 569, 598"}]},{"t":"case","label":"National Rifle Association v. Cuomo","cite":"525 F. Supp. 3d 382","y":2021,"court":"N.D.N.Y.","url":"https://www.courtlistener.com/c/F.%20Supp.%203d/525/382/","by":{"0":"27"},"q":[{"src":"brief","b":0,"text":"comply and I’ll look the other way.","cite":"525 F. Supp. 3d 382, 392"}]},{"t":"case","label":"Nken v. Holder","cite":"556 U.S. 418","y":2009,"id":"2008/08-681","sc":1,"by":{"0":"47"}},{"t":"case","label":"O’Handley v. Weber","cite":"62 F.4th 1145","y":2023,"court":"filed June 8","url":"https://www.courtlistener.com/c/F.4th/62/1145/","by":{"0":"28, 30, 39, 40, 45"},"q":[{"src":"brief","b":0,"text":"overwhelm the private party and essentially compel the party to act in a certain way.","cite":"62 F.4th 1145, 1158"},{"src":"brief","b":0,"text":"Agencies are permitted to communicate in a non-threatening manner with the entities they oversee without creating a constitutional violation.","cite":"62 F.4th at 1163"}]},{"t":"case","label":"O’Shea v. Littleton","cite":"414 U.S. 488","y":1974,"id":"1973/72-953","sc":1,"by":{"0":"19, 21","2":"28","3":"4"},"q":[{"src":"brief","b":0,"text":"real and immediate threat of repeated injury.","cite":"414 U.S. 488, 495-496"},{"src":"brief","b":0,"text":"real and immediate threat of repeated injury","cite":"414 U.S. at 496"},{"src":"brief","b":2,"text":"real and immediate threat of repeated injury.","cite":"414 U.S. 488, 495-96"},{"src":"brief","b":3,"text":"real and immediate threat of repeated injury,","cite":"414 U.S. 488, 495-496"}]},{"t":"case","label":"Peery v. Chicago Housing Authority","cite":"791 F.3d 788","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/791/788/","by":{"0":"28","3":"13"},"q":[{"src":"brief","b":0,"text":"[g]overnment officials and agencies spend a great deal of time urging private persons and firms and other institutions to change their behavior.","cite":"791 F.3d 788, 790"},{"src":"brief","b":3,"text":"Government officials and agencies spend a great deal of time urging private persons and firms and other institutions to change their behavior.","cite":"791 F.3d 788, 790"}]},{"t":"case","label":"Penthouse International, Ltd. v. Meese","cite":"939 F.2d 1011","y":1991,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.2d/939/1011/","by":{"0":"23, 24, 35","3":"18"},"q":[{"src":"brief","b":0,"text":"[w]e know of no case in which the first amendment has been held to be implicated by governmental action consisting of no more than governmental criticism of the speech’s content.","cite":"939 F.2d at 1016"},{"src":"brief","b":3,"text":"officials surely must be expected to be free to speak out to criticize practices, even in a condemnatory fashion, that they might not have the statutory or even constitutional authority to regulate.","cite":"939 F.2d 1011, 1015"},{"src":"argument","who":"Mr. Fletcher","text":"That's Penthouse versus Meese, Judge Silberman's opinion there. That's what happens when the White House Press Secretary calls up The New York Times and says that was a bad op-ed, you shouldn't run op-eds like that anymore."}]},{"t":"case","label":"Pleasant Grove City v. Summum","cite":"555 U.S. 460","y":2009,"id":"2008/07-665","sc":1,"by":{"0":"2, 23, 45","3":"7, 16"},"q":[{"src":"brief","b":0,"text":"the Free Speech Clause has no application.","cite":"555 U.S. 460, 467"},{"src":"brief","b":0,"text":"If the citizenry objects, newly elected officials later could espouse some different or contrary position.","cite":"555 U.S. at 468"}]},{"t":"case","label":"Roman Catholic Diocese of Brooklyn v. Cuomo","cite":"141 S. Ct. 63","y":2020,"id":"2020/20a87","sc":1,"by":{"0":"46"}},{"t":"case","label":"Schmidt v. Lessard","cite":"414 U.S. 473","y":1974,"id":"1973/73-568","sc":1,"by":{"0":"50"}},{"t":"case","label":"Schneckloth v. Bustamonte","cite":"412 U.S. 218","y":1973,"id":"1972/71-732","sc":1,"by":{"0":"41"},"q":[{"src":"brief","b":0,"text":"that coercive police activity is a necessary predicate to the finding that a confession is not ‘voluntary.’","cite":"412 U.S. 218"}]},{"t":"case","label":"Shurtleff v. City of Boston","cite":"596 U.S. 243","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/243/","sc":1,"by":{"0":"23"},"q":[{"src":"brief","b":0,"text":"to check the government when it speaks.","cite":"596 U.S. 243, 252"}]},{"t":"case","label":"TransUnion LLC v. Ramirez","cite":"141 S. Ct. 2190","y":2021,"id":"2020/20-297","sc":1,"by":{"0":"16, 21","3":"6"},"q":[{"src":"brief","b":0,"text":"for each form of relief that they seek,","cite":"141 S. Ct. 2190, 2208"},{"src":"brief","b":0,"text":"asserted informational injury that causes no adverse effects cannot satisfy Article III.","cite":"141 S. Ct. at 2214"}]},{"t":"case","label":"Twitter, Inc. v. Taamneh","cite":"598 U.S. 471","y":2023,"id":"2022/21-1496","sc":1,"by":{"0":"3"},"q":[{"src":"argument","who":"Mr. Fletcher","text":"Kennedy, Junior, suppressed by Twitter and she says, that's an indication that my harms are traceable to the government because the government was talking about Robert F."},{"src":"argument","who":"Justice Barrett","text":"And -- and that was actually about his own Facebook account. Or there was another change that was -- exchange that was actually about somebody impersonating the President's granddaughter on Twitter."},{"src":"argument","who":"Justice Kagan","text":"What's so pernicious here is that you don't see any of these facts in this record unless we get discovery, which is when the -- when Rob Flaherty, who's Deputy Assistant to the President, sends an email to Facebook or to Twitter and complains that they're not doing enough to censor what they view as vaccine hesitancy speech."}]},{"t":"case","label":"United States v. American Library Association","cite":"539 U.S. 194","y":2003,"id":"2002/02-361","sc":1,"by":{"0":"22"}},{"t":"case","label":"United States v. Texas","cite":"599 U.S. 670","y":2023,"id":"2022/22-58","sc":1,"by":{"0":"16, 17, 46"},"q":[{"src":"brief","b":0,"text":"The principle of Article III standing is ‘built on a single basic idea—the idea of separation of powers.’","cite":"599 U.S. 670, 675"}]},{"t":"case","label":"Valley Forge Christian College v. Americans United for Separation of Church & State, Inc.","cite":"454 U.S. 464","y":1982,"id":"1981/80-327","sc":1,"by":{"0":"17"},"q":[{"src":"brief","b":0,"text":"forums for the ventilation of public grievances,","cite":"454 U.S. 464, 473"}]},{"t":"case","label":"Virginia State Board of Pharmacy v. Virginia Citizens Consumer Council, Inc.","cite":"425 U.S. 748","y":1976,"id":"1975/74-895","sc":1,"by":{"0":"21","2":"23"},"q":[{"src":"brief","b":2,"text":"where a speaker exists…, the protection afforded is to the communication, to its source and to its recipients both.","cite":"425 U.S. 748, 756"}]},{"t":"case","label":"Winter v. NRDC, Inc.","cite":"555 U.S. 7","y":2008,"id":"2008/07-1239","sc":1,"by":{"0":"45, 46"},"q":[{"src":"brief","b":0,"text":"An injunction is a matter of equitable discretion; it does not follow from success on the merits as a matter of course.","cite":"555 U.S. 7, 32"}]},{"t":"const","label":"Amendment I","clauses":[["establishment","Establishment Clause"],["free-exercise","Free Exercise Clause"],["free-speech","Free Speech Clause"],["free-press","Free Press Clause"],["assembly-petition","Assembly, Petition and Association"]],"text":"Congress shall make no law respecting an establishment of religion, or prohibiting the free exercise thereof; or abridging the freedom of speech, or of the press; or the right of the people peaceably to assemble, and to petition the Government for a redress of grievances.","by":{"0":"2, 3, 8, 9, 14, 15, 17, 20-23, 25, 29, 30, 34, 36, 45, 46","3":"1, 2, 7, 8, 14, 16, 17, 21"}},{"t":"usc","label":"47 U.S.C. § 230","url":"https://www.law.cornell.edu/uscode/text/47/230","stext":{"head":"§230. Protection for private blocking and screening of offensive material","paras":[[0,"(a) Findings"],[0,"The Congress finds the following:"],[1,"(1) The rapidly developing array of Internet and other interactive computer services available to individual Americans represent an extraordinary advance in the availability of educational and informational resources to our citizens."],[1,"(2) These services offer users a great degree of control over the information that they receive, as well as the potential for even greater control in the future as technology develops."],[1,"(3) The Internet and other interactive computer services offer a forum for a true diversity of political discourse, unique opportunities for cultural development, and myriad avenues for intellectual activity."],[1,"(4) The Internet and other interactive computer services have flourished, to the benefit of all Americans, with a minimum of government regulation."],[1,"(5) Increasingly Americans are relying on interactive media for a variety of political, educational, cultural, and entertainment services."],[0,"(b) Policy"],[0,"It is the policy of the United States—"],[1,"(1) to promote the continued development of the Internet and other interactive computer services and other interactive media;"],[1,"(2) to preserve the vibrant and competitive free market that presently exists for the Internet and other interactive computer services, unfettered by Federal or State regulation;"],[1,"(3) to encourage the development of technologies which maximize user control over what information is received by individuals, families, and schools who use the Internet and other interactive computer services;"],[1,"(4) to remove disincentives for the development and utilization of blocking and filtering technologies that empower parents to restrict their children's access to objectionable or inappropriate online material; and"],[1,"(5) to ensure vigorous enforcement of Federal criminal laws to deter and punish trafficking in obscenity, stalking, and harassment by means of computer."],[0,"(c) Protection for \"Good Samaritan\" blocking and screening of offensive material"],[0,"(1) Treatment of publisher or speaker"],[1,"No provider or user of an interactive computer service shall be treated as the publisher or speaker of any information provided by another information content provider."],[0,"(2) Civil liability"],[1,"No provider or user of an interactive computer service shall be held liable on account of—"],[2,"(A) any action voluntarily taken in good faith to restrict access to or availability of material that the provider or user considers to be obscene, lewd, lascivious, filthy, excessively violent, harassing, or otherwise objectionable, whether or not such material is constitutionally protected; or"],[2,"(B) any action taken to enable or make available to information content providers or others the technical means to restrict access to material described in paragraph (1).1"],[0,"(d) Obligations of interactive computer service"],[0,"A provider of interactive computer service shall, at the time of entering an agreement with a customer for the provision of interactive computer service and in a manner deemed appropriate by the provider, notify such customer that parental control protections (such as computer hardware, software, or filtering services) are commercially available that may assist the customer in limiting access to material that is harmful to minors. Such notice shall identify, or provide the customer with access to information identifying, current providers of such protections."],[0,"(e) Effect on other laws"],[0,"(1) No effect on criminal law"],[1,"Nothing in this section shall be construed to impair the enforcement of section 223 or 231 of this title, chapter 71 (relating to obscenity) or 110 (relating to sexual exploitation of children) of title 18, or any other Federal criminal statute."],[0,"(2) No effect on intellectual property law"],[1,"Nothing in this section shall be construed to limit or expand any law pertaining to intellectual property."],[0,"(3) State law"],[1,"Nothing in this section shall be construed to prevent any State from enforcing any State law that is consistent with this section. No cause of action may be brought and no liability may be imposed under any State or local law that is inconsistent with this section."],[0,"(4) No effect on communications privacy law"],[1,"Nothing in this section shall be construed to limit the application of the Electronic Communications Privacy Act of 1986 or any of the amendments made by such Act, or any similar State law."],[0,"(5) No effect on sex trafficking law"],[1,"Nothing in this section (other than subsection (c)(2)(A)) shall be construed to impair or limit—"],[2,"(A) any claim in a civil action brought under section 1595 of title 18, if the conduct underlying the claim constitutes a violation of section 1591 of that title;"],[2,"(B) any charge in a criminal prosecution brought under State law if the conduct underlying the charge would constitute a violation of section 1591 of title 18; or"],[2,"(C) any charge in a criminal prosecution brought under State law if the conduct underlying the charge would constitute a violation of section 2421A of title 18, and promotion or facilitation of prostitution is illegal in the jurisdiction where the defendant's promotion or facilitation of prostitution was targeted."],[0,"(f) Definitions"],[0,"As used in this section:"],[0,"(1) Internet"],[1,"The term \"Internet\" means the international computer network of both Federal and non-Federal interoperable packet switched data networks."],[0,"(2) Interactive computer service"],[1,"The term \"interactive computer service\" means any information service, system, or access software provider that provides or enables computer access by multiple users to a computer server, including specifically a service or system that provides access to the Internet and such systems operated or services offered by libraries or educational institutions."],[0,"(3) Information content provider"],[1,"The term \"information content provider\" means any person or entity that is responsible, in whole or in part, for the creation or development of information provided through the Internet or any other interactive computer service."],[0,"(4) Access software provider"],[1,"The term \"access software provider\" means a provider of software (including client or server software), or enabling tools that do any one or more of the following:"],[2,"(A) filter, screen, allow, or disallow content;"],[2,"(B) pick, choose, analyze, or digest content; or"],[2,"(C) transmit, receive, display, forward, cache, search, subset, organize, reorganize, or translate content."]],"more":false,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/47/230?type=usc&year=mostrecent&link-type=html"},"by":{"0":"32"},"q":[{"src":"argument","who":"Justice Alito","text":"And so I thought: You know, the only reason why this is taking place is because the federal government has got Section 230 and antitrust in its pocket and it's -- to mix my metaphors, and it's got these big clubs available for -- available to it, and so it's treating Facebook and these other platforms like they're subordinates."},{"src":"argument","who":"Justice Gorsuch","text":"And a -- a threat or an inducement with respect to Section 230 qualify?"},{"src":"argument","who":"Justice Gorsuch","text":"And is that -- would that be enough to say we're going to -- if you don't do X, we are going to change our position on Section 230?"}]},{"t":"usc","label":"18 U.S.C. § 2702","url":"https://www.law.cornell.edu/uscode/text/18/2702","by":{"0":"48"}},{"t":"reg","label":"3 C.F.R. pt. 129","url":"https://www.ecfr.gov/current/title-3/part-129","by":{"0":"24"}},{"t":"usc","label":"22 U.S.C. § 611","url":"https://www.law.cornell.edu/uscode/text/22/611","by":{"1":"7"}},{"t":"usc","label":"2 U.S.C. § 1601","url":"https://www.law.cornell.edu/uscode/text/2/1601","by":{"1":"7"}},{"t":"case","label":"Anderson v. City of Bessemer City","cite":"470 U.S. 564","y":1985,"id":"1984/83-1623","sc":1,"by":{"2":"2"}},{"t":"case","label":"Backpage.com v. Dart","cite":"807 F.3d 229","y":2015,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/807/229/","by":{"2":"38"},"q":[{"src":"argument","who":"Justice Kavanaugh","text":"I think Judge Posner made this -- this point in Backpage versus Dart, which is you could have a threatener who threatens the recipient, the recipient says no, and so the threatener packs their tent and walks away."}]},{"t":"case","label":"Biden v. Knight First Amend. Inst. at Columbia Univ.","cite":"141 S. Ct. 1220","y":2021,"url":"https://www.courtlistener.com/c/S.%20Ct./141/1220/","sc":1,"by":{"2":"38","3":"8, 21"},"q":[{"src":"argument","who":"Mr. Fletcher","text":"So I think that one is much harder. That's a statement that President Biden made off the cuff to the press."},{"src":"argument","who":"Justice Kagan","text":"And the way this issue arises is when maybe you have a foreign actor who tweets, you know, I love Biden, and there are 20 million people who wish to retweet that, repost that, with their own comments, saying, heck, yeah, I love Biden too."}]},{"t":"case","label":"Borough of Duryea, Pa. v. Guarnieri","cite":"564 U.S. 379","y":2011,"id":"2010/09-1476","sc":1,"by":{"2":"26"}},{"t":"case","label":"Brandenburg v. Ohio","cite":"395 U.S. 444","y":1969,"id":"1968/492","sc":1,"by":{"2":"35","3":"16"}},{"t":"case","label":"Burton v. Wilmington Parking Auth.","cite":"365 U.S. 715","y":1961,"id":"1960/164","sc":1,"by":{"2":"31, 45","3":"18"}},{"t":"case","label":"Christian Legal Soc’y v. Walker","cite":"453 F.3d 853","y":2006,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/453/853/","by":{"2":"18, 49"},"q":[{"src":"brief","b":2,"text":"[I]njunctions protecting First Amendment freedoms are always in the public interest,","cite":"453 F.3d 853, 859"},{"src":"brief","b":2,"text":"injunctions protecting First Amendment freedoms are always in the public interest,","cite":"453 F.3d at 859"}]},{"t":"case","label":"Crowe v. Lucas","cite":"595 F.2d 985","y":1979,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/595/985/","by":{"2":"43"}},{"t":"case","label":"Dennis v. Sparks","cite":"449 U.S. 24","y":1980,"id":"1980/79-1186","sc":1,"by":{"2":"43","3":"21"}},{"t":"case","label":"Dep’t of Commerce v. New York","cite":"139 S. Ct. 2551","y":2019,"id":"2018/18-966","sc":1,"by":{"2":"21, 22","3":"4"},"q":[{"src":"brief","b":2,"text":"third parties will likely react in predictable ways.","cite":"139 S. Ct. 2551, 2566"},{"src":"brief","b":2,"text":"the predictable effect of Government action on [their] decisions,","cite":"139 S. Ct. at 2566"}]},{"t":"case","label":"Dombrowski v. Pfister","cite":"380 U.S. 479","y":1965,"id":"1964/52","sc":1,"by":{"2":"25, 30"}},{"t":"case","label":"Dossett v. First State Bank","cite":"399 F.3d 940","y":2005,"court":"8th Cir.","url":"https://www.courtlistener.com/c/F.3d/399/940/","by":{"2":"36"}},{"t":"case","label":"Elonis v. United States","cite":"575 U.S. 723","y":2015,"id":"2014/13-983","sc":1,"by":{"2":"38"}},{"t":"case","label":"Frazier v. Bd. of Trs. of Nw. Miss. Reg’l Med. Ctr.","cite":"765 F.2d 1278","y":1985,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/765/1278/","by":{"2":"34, 35"}},{"t":"case","label":"George v. Edholm","cite":"752 F.3d 1206","y":2014,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/752/1206/","by":{"2":"47"}},{"t":"case","label":"Harvey v. Plains Twp. Police Dep’t","cite":"421 F.3d 185","y":2005,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/421/185/","by":{"2":"47"},"q":[{"src":"brief","b":2,"text":"it seems entirely proper to find that the state actor engaged in state action, including whatever actions the private party was compelled to undertake.","cite":"421 F.3d at 196 n.13"}]},{"t":"case","label":"Horvath v. Westport Libr. Ass’n","cite":"362 F.3d 147","y":2004,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/362/147/","by":{"2":"45"}},{"t":"case","label":"Kach v. Hose","cite":"589 F.3d 626","y":2009,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.3d/589/626/","by":{"2":"34"}},{"t":"case","label":"Kowalski v. Tesmer","cite":"543 U.S. 125","y":2004,"id":"2004/03-407","sc":1,"by":{"2":"30, 31","3":"7"},"q":[{"src":"brief","b":2,"text":"[w]ithin the context of the First Amendment.","cite":"543 U.S. 125, 130"},{"src":"brief","b":2,"text":"when enforcement of the challenged restriction against the litigant would result indirectly in the violation of third parties’ rights.","cite":"543 U.S. at 130"}]},{"t":"case","label":"Laird v. Tatum","cite":"408 U.S. 1","y":1972,"id":"1971/71-288","sc":1,"by":{"2":"27","3":"3"},"q":[{"src":"brief","b":3,"text":"a broad-scale investigation, conducted by themselves as private parties armed with the subpoena power of a federal district court,","cite":"408 U.S. 1, 14"}]},{"t":"case","label":"Mahanoy Area Sch. Dist. v. B. L.","cite":"141 S. Ct. 2038","y":2021,"id":"2020/20-255","sc":1,"by":{"2":"26"},"q":[{"src":"brief","b":2,"text":"Our representative democracy only works if we protect the ‘marketplace of ideas.’ This free exchange facilitates an informed public opinion, which, when transmitted to lawmakers, helps produce laws that reflect the People’s will.","cite":"141 S. Ct. 2038, 2046"}]},{"t":"case","label":"Matal v. Tam","cite":"582 U.S. 218","y":2017,"id":"2016/15-1293","sc":1,"by":{"2":"2"},"q":[{"src":"brief","b":2,"text":"government [to] silence or muffle the expression of disfavored viewpoints.","cite":"582 U.S. 218, 235"}]},{"t":"case","label":"McIntyre v. Ohio Elec. Comm’n","cite":"514 U.S. 334","y":1995,"id":"1994/93-986","sc":1,"by":{"2":"31"}},{"t":"case","label":"Neb. Press Ass’n v. Stuart","cite":"427 U.S. 539","y":1976,"id":"1975/75-817","sc":1,"by":{"2":"31"},"q":[{"src":"argument","who":"Mr. Fletcher","text":"Similarly, I think both the Fifth Circuit and my friends have really said that the crux of what they claim was coercion here was what happened in July of 2021 when the Surgeon General, the White House Press Secretary, and the President himself made statements criticizing the platforms' practices on misinformation and false statements about COVID vaccines and calling on them to do better."},{"src":"argument","who":"Justice Alito","text":"Would you do that to The -- to The New York Times or The Wall Street Journal or the Associated Press or any other big newspaper or wire service?"},{"src":"argument","who":"Mr. Fletcher","text":"When the White House Press Secretary on July 16th is asked about this by the press at the time, what she says is, of course, we talk to the platforms just the way we talk to all of you when we have concerns about what you're doing, when we have information that you might find helpful."}]},{"t":"case","label":"Newberry v. United States","cite":"256 U.S. 232","y":1921,"id":"scdb/1920-108","sc":1,"by":{"2":"37"}},{"t":"case","label":"N.J. Bankers Ass’n v. Att’y Gen.","cite":"49 F.4th 849","y":2022,"court":"3d Cir.","url":"https://www.courtlistener.com/c/F.4th/49/849/","by":{"2":"30"}},{"t":"case","label":"Norwood v. Harrison","cite":"413 U.S. 455","y":1973,"id":"1972/72-77","sc":1,"by":{"2":"2, 31, 36","3":"15, 17"},"q":[{"src":"brief","b":2,"text":"It is … axiomatic that a state may not induce, encourage or promote private persons to accomplish what it is constitutionally forbidden to accomplish.","cite":"413 U.S. 455, 465"},{"src":"brief","b":2,"text":"axiomatic that [Government] may not induce, encourage or promote private persons to accomplish what it is constitutionally forbidden to accomplish.","cite":"413 U.S. at 465"},{"src":"brief","b":3,"text":"what [the government] is constitutionally forbidden to accomplish","cite":"413 U.S. at 465"},{"src":"opinion","who":"Justice Alito, dissenting","text":"`to accomplish what . . . is constitutionally forbidden.'","cite":"413 U. S. 455, 465"},{"src":"argument","who":"Justice Thomas","text":"And I would point the Court to what it said in Norwood, which is the Court -- or the -- the government cannot induce, encourage, and promote private actors to do directly what the government can't itself do directly."},{"src":"argument","who":"Justice Sotomayor","text":"The fundamental principle -- and this comes from Norwood and it's central to this Court's First Amendment cases, its Fourth Amendment cases -- is that the government can't do indirectly what it's prohibited from doing directly."},{"src":"argument","who":"Justice Barrett","text":"I guess the top-line legal standard I would start with was this Court's line at 635 in Norwood, which is the Court can't do indirectly what it's constitutionally prohibited from doing directly."}]},{"t":"case","label":"N.Y. Times Co. v. Sullivan","cite":"376 U.S. 254","y":1964,"id":"1963/39","sc":1,"by":{"2":"46"},"q":[{"src":"brief","b":2,"text":"profound . . . commitment to the principle that debate on public issues should be uninhibited, robust, and wide-open.","cite":"376 U.S. 254, 270"},{"src":"argument","who":"Justice Alito","text":"Would you do that to The -- to The New York Times or The Wall Street Journal or the Associated Press or any other big newspaper or wire service?"},{"src":"argument","who":"Mr. Fletcher","text":"That's what happens when the White House Press Secretary calls up The New York Times and says that was a bad op-ed, you shouldn't run op-eds like that anymore."},{"src":"argument","who":"Justice Kagan","text":"And I think it makes a difference, Justice Kagan, that you have an intermediary here who really has no incentive to itself defend Jim Hoft's speech or to defend Jill Hines's speech. In The New York Times's hypothetical, you have a story, a publication that itself is familiar with those kinds of --"}]},{"t":"case","label":"Okwedy v. Molinari","cite":"333 F.3d 339","y":2003,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/333/339/","by":{"2":"38"},"q":[{"src":"argument","who":"Justice Barrett","text":"Justice Sotomayor has a panel, a procuring panel decision called Okwedy versus Molinari in the Second Circuit that addressed this issue about authority, and the issue in that case was that the borough president of Staten Island didn't have authority to take down a particular billboard, but the court still said that the fact that the recipient thought that the borough president might be able to use whatever authority he did have to cause trouble for the billboard owner, that was enough."}]},{"t":"case","label":"Opulent Life Church v. City of Holly Springs","cite":"697 F.3d 279","y":2012,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.3d/697/279/","by":{"2":"24"}},{"t":"case","label":"Packingham v. North Carolina","cite":"582 U.S. 98","y":2017,"id":"2016/15-1194","sc":1,"by":{"2":"1, 17, 22"}},{"t":"case","label":"Proffitt v. Ridgway","cite":"279 F.3d 503","y":2002,"court":"7th Cir.","url":"https://www.courtlistener.com/c/F.3d/279/503/","by":{"2":"43, 44"},"q":[{"src":"brief","b":2,"text":"is liable . . . for the wrongful acts of the other conspirators committed within the scope of the conspiracy.","cite":"279 F.3d 503, 507"}]},{"t":"case","label":"Quantity of Copies of Books v. Kansas","cite":"378 U.S. 205","y":1964,"id":"1963/449","sc":1,"by":{"2":"37"},"q":[{"src":"brief","b":2,"text":"draw [a] blueprint[] showing how to avoid the First Amendment’s guarantee of freedom[] of speech","cite":"378 U.S. 205, 215"}]},{"t":"case","label":"Rattner v. Netburn","cite":"930 F.2d 204","y":1991,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/930/204/","by":{"2":"38"}},{"t":"case","label":"Rawson v. Recovery Innovations, Inc.","cite":"975 F.3d 742","y":2020,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/975/742/","by":{"2":"32"}},{"t":"case","label":"Rayburn ex rel. Rayburn v. Hogue","cite":"241 F.3d 1341","y":2001,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.3d/241/1341/","by":{"2":"34"}},{"t":"case","label":"Regal Knitwear Co. v. NLRB","cite":"324 U.S. 9","y":1945,"id":"scdb/1944-125","sc":1,"by":{"2":"50"}},{"t":"case","label":"Rivera v. Rhode Island","cite":"402 F.3d 27","y":2005,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/402/27/","by":{"2":"37"}},{"t":"case","label":"Roberts v. La. Downs, Inc.","cite":"742 F.2d 221","y":1984,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/742/221/","by":{"2":"44"},"q":[{"src":"brief","b":2,"text":"decisions [in that area] may be considered to bear the imprimatur of the state.","cite":"742 F.2d 221, 228"}]},{"t":"case","label":"Rosemond v. United States","cite":"572 U.S. 65","y":2014,"id":"2013/12-895","sc":1,"by":{"2":"35"}},{"t":"case","label":"Rudd v. City of Norton Shores","cite":"977 F.3d 503","y":2020,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/977/503/","by":{"2":"43"}},{"t":"case","label":"Rumsfeld v. F. for Acad. & Institutional Rts.","cite":"547 U.S. 47","y":2006,"id":"2005/04-1152","sc":1,"by":{"2":"19"},"q":[{"src":"brief","b":2,"text":"[T]he presence of one party with standing is sufficient to satisfy Article III’s case-or-controversy requirement.","cite":"547 U.S. 47, 52 n.2"}]},{"t":"case","label":"Skinner v. Ry. Lab. Execs.’ Ass’n","cite":"489 U.S. 602","y":1989,"id":"1988/87-1555","sc":1,"by":{"2":"32, 34","3":"13, 14"},"q":[{"src":"brief","b":2,"text":"did more than adopt a passive position toward","cite":"489 U.S. 602, 615-16"},{"src":"brief","b":3,"text":"more than adopt a passive position toward","cite":"489 U.S. 602, 615-616"}]},{"t":"case","label":"Smith v. Wade","cite":"461 U.S. 30","y":1983,"id":"1982/81-1196","sc":1,"by":{"2":"37"}},{"t":"case","label":"Story v. Jersey City & B.P.P.R. Co.","cite":"16 N.J. Eq. 13","y":1863,"court":"N.J. Ch.","url":"https://www.courtlistener.com/c/N.J.%20Eq./16/13/","by":{"2":"27"},"q":[{"src":"brief","b":2,"text":"an infringement of the rights of the people and of their representatives.","cite":"16 N.J. Eq. 13, 20-21"}]},{"t":"case","label":"Students for Fair Admissions, Inc. v. President & Fellows of Harvard Coll.","cite":"600 U.S. 181","y":2023,"id":"2022/20-1199","sc":1,"by":{"2":"47"}},{"t":"case","label":"Susan B. Anthony List v. Driehaus","cite":"573 U.S. 149","y":2014,"id":"2013/13-193","sc":1,"by":{"2":"18"},"q":[{"src":"brief","b":2,"text":"To establish Article III standing, a plaintiff must show (1) an ‘injury in fact,’ (2) a sufficient ‘causal connection between the injury and the conduct complained of,’ and (3) a ‘likelihood’ that the injury ‘will be redressed by a favorable decision.’","cite":"573 U.S. 149, 157–58"}]},{"t":"case","label":"Sutton v. Providence St. Joseph Med. Ctr.","cite":"192 F.3d 826","y":1999,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/192/826/","by":{"2":"47"}},{"t":"case","label":"Taggart v. Lorenzen","cite":"139 S. Ct. 1795","y":2019,"id":"2018/18-489","sc":1,"by":{"2":"50","3":"22"},"q":[{"src":"brief","b":2,"text":"civil contempt should not be resorted to where there is a fair ground of doubt as to the wrongfulness of the defendant’s conduct.","cite":"139 S. Ct. 1795, 1801"},{"src":"brief","b":3,"text":"where there is a fair ground of doubt as to the wrongfulness of the defendant’s conduct.","cite":"139 S. Ct. 1795, 1801"}]},{"t":"case","label":"Terminiello v. Chicago","cite":"337 U.S. 1","y":1949,"id":"1940-1955/337us1","sc":1,"by":{"2":"26"},"q":[{"src":"brief","b":2,"text":"[I]t it is only through free debate and free exchange of ideas that government remains responsive to the will of the people….","cite":"337 U.S. 1, 4"}]},{"t":"case","label":"Trump v. Hawaii","cite":"138 S. Ct. 2392","y":2018,"id":"2017/17-965","sc":1,"by":{"2":"51, 52"},"q":[{"src":"brief","b":2,"text":"necessary to provide complete relief to the Plaintiffs,","cite":"138 S. Ct. 2392, 2446 n.13"},{"src":"brief","b":2,"text":"advantage[s] nonparties, that benefit [i]s merely incidental.","cite":"138 S. Ct. at 2427"}]},{"t":"case","label":"United States v. Fulmer","cite":"108 F.3d 1486","y":1997,"court":"1st Cir.","url":"https://www.courtlistener.com/c/F.3d/108/1486/","by":{"2":"39"}},{"t":"case","label":"United States v. Hansen","cite":"599 U.S. 762","y":2023,"id":"2022/22-179","sc":1,"by":{"2":"35, 36"},"q":[{"src":"brief","b":2,"text":"intent to bring about a particular unlawful act,","cite":"599 U.S. 762, 771"}]},{"t":"case","label":"United States v. Houston","cite":"792 F.3d 663","y":2015,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/792/663/","by":{"2":"39"}},{"t":"case","label":"United States v. Philip Morris USA Inc.","cite":"566 F.3d 1095","y":2009,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/566/1095/","by":{"2":"51"},"q":[{"src":"brief","b":2,"text":"record of continuing and persistent violations.","cite":"566 F.3d 1095, 1137"}]},{"t":"case","label":"United States v. Sineneng-Smith","cite":"140 S. Ct. 1575","y":2020,"id":"2019/19-67","sc":1,"by":{"2":"24"}},{"t":"case","label":"United States v. Stein","cite":"541 F.3d 130","y":2008,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.3d/541/130/","by":{"2":"36, 45"}},{"t":"case","label":"United States v. Williams","cite":"553 U.S. 285","y":2008,"id":"2007/06-694","sc":1,"by":{"2":"35"},"q":[{"src":"brief","b":2,"text":"the recommendation of a particular piece of purported child pornography.","cite":"553 U.S. 285, 299-300"}]},{"t":"case","label":"United States Telecom Ass’n v. FCC","cite":"855 F.3d 381","y":2017,"court":"D.C. Cir.","url":"https://www.courtlistener.com/c/F.3d/855/381/","by":{"2":"32, 33"},"q":[{"src":"brief","b":2,"text":"may not tell Internet service providers how to exercise their editorial discretion about what content to carry or favor.","cite":"855 F.3d 381, 435"},{"src":"brief","b":2,"text":"keep [their] hands off [platforms’] editorial decisions,","cite":"855 F.3d at 435"}]},{"t":"case","label":"Utah Republican Party v. Cox","cite":"892 F.3d 1066","y":2018,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/892/1066/","by":{"2":"26"}},{"t":"case","label":"W. Va. State Bd. of Educ. v. Barnette","cite":"319 U.S. 624","y":1943,"id":"1940-1955/319us624","sc":1,"by":{"2":"31"}},{"t":"case","label":"Warth v. Seldin","cite":"422 U.S. 490","y":1975,"id":"1974/73-2024","sc":1,"by":{"2":"30"}},{"t":"case","label":"Watts v. United States","cite":"394 U.S. 705","y":1969,"id":"1968/1107_misc","sc":1,"by":{"2":"39"}},{"t":"case","label":"FEC v. Ted Cruz for Senate","cite":"596 U.S. 289","y":2022,"url":"https://supreme.justia.com/cases/federal/us/596/289/","sc":1,"by":{"3":"6"},"q":[{"src":"brief","b":3,"text":"[A] litigant cannot, ‘by virtue of his standing to challenge one government action, challenge other governmental actions that did not injure him.’","cite":"596 U.S. 289, 301"}]},{"t":"case","label":"Hollingsworth v. Perry","cite":"570 U.S. 693","y":2013,"id":"2012/12-144","sc":1,"by":{"3":"6"},"q":[{"src":"brief","b":3,"text":"repeatedly held that such a ‘generalized grievance,’ no matter how sincere, is insufficient to confer standing.","cite":"570 U.S. 693, 706"}]},{"t":"case","label":"Jackson v. Metropolitan Edison Co.","cite":"419 U.S. 345","y":1974,"id":"1974/73-5845","sc":1,"by":{"3":"19"}},{"t":"case","label":"Rendell-Baker v. Kohn","cite":"457 U.S. 830","y":1982,"id":"1981/80-2102","sc":1,"by":{"3":"19"}},{"t":"case","label":"Simon v. Eastern Kentucky Welfare Rights Organization","cite":"426 U.S. 26","y":1976,"id":"1975/74-1124","sc":1,"by":{"3":"4"}},{"t":"case","label":"Southeastern Promotions, Ltd. v. Conrad","cite":"420 U.S. 546","y":1975,"id":"1974/73-1004","sc":1,"by":{"3":"16"}},{"t":"const","label":"Amendment IV","clauses":[["fourth-amendment","Fourth Amendment"]],"text":"The right of the people to be secure in their persons, houses, papers, and effects, against unreasonable searches and seizures, shall not be violated, and no Warrants shall issue, but upon probable cause, supported by Oath or affirmation, and particularly describing the place to be searched, and the persons or things to be seized.","by":{"3":"14"}},{"t":"const","label":"Amendment XIV","clauses":[["citizenship-clause","Citizenship Clause"],["privileges-or-immunities","Privileges or Immunities Clause"],["due-process-14","Due Process Clause (Fourteenth Amendment)"],["equal-protection","Equal Protection Clause"],["disqualification","Disqualification Clause (Section 3)"],["enforcement-14","Enforcement Clause (Section 5)"]],"by":{"3":"15, 21"}}]};